<?php
declare(strict_types=1);
namespace SiteCms;

final class TemplateAdmin {
    public function __construct(private Content $content,private Access $access,private array $configuration) {}
    public function page(array $actor,string $method):array {
        $this->access->require($actor,'settings');$site=$this->content->site;$record=$site->get('templates');$templates=$record['value'];$error='';$selected=(string)($_GET['edit'] ?? '');$candidate=null;
        foreach($templates as $template){if($template['id']===$selected){$candidate=$template;}}
        if($selected==='new'){$candidate=['id'=>'t-'.Store::id(),'name'=>'Neue Vorlage','types'=>[array_key_first($this->content->schema->types)],'default_for'=>[],'sections'=>[['id'=>'section-'.Store::id(),'layout'=>'one','tone'=>'plain','spacing'=>'normal','columns'=>[[['id'=>'title-'.Store::id(),'kind'=>'field','field'=>'title'],['id'=>'body-'.Store::id(),'kind'=>'field','field'=>'body']]]]]];}
        if($selected==='new' && !isset($this->content->schema->types[$candidate['types'][0]]['fields']['body'])){array_pop($candidate['sections'][0]['columns'][0]);}
        if($method==='POST'){
            try{
                if(isset($_POST['restore'])){$site->restore('templates',(string)$_POST['restore'],(int)($_POST['version'] ?? -1),$actor);header('Location: /admin/templates/?saved=1',true,303);return ['',''];}
                if(isset($_POST['remove'])){$templates=array_values(array_filter($templates,static fn($row)=>$row['id']!==(string)$_POST['remove']));$site->save('templates',(int)($_POST['version'] ?? -1),$templates,$actor);header('Location: /admin/templates/?saved=1',true,303);return ['',''];}
                $raw=$_POST['template_json'] ?? '';if(!is_string($raw) || strlen($raw)>1024*1024){throw new HttpError(422,'Vorlage zu groß.');}
                try{$candidate=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new HttpError(422,'Ungültige Vorlage.');}if(!is_array($candidate)){throw new HttpError(422,'Ungültige Vorlage.');}
                $candidate['name']=(string)($_POST['name'] ?? '');$candidate['types']=array_values((array)($_POST['types'] ?? []));$candidate['default_for']=array_values((array)($_POST['default_for'] ?? []));
                if($selected!=='new' && (!$selected || ($candidate['id'] ?? '')!==$selected)){throw new HttpError(422,'Vorlagen-ID stimmt nicht überein.');}
                $found=false;foreach($templates as &$template){if($template['id']===$candidate['id']){$template=$candidate;$found=true;}}unset($template);if(!$found){$templates[]=$candidate;}
                $site->save('templates',(int)($_POST['version'] ?? -1),$templates,$actor);header('Location: /admin/templates/?edit='.rawurlencode($candidate['id']).'&saved=1',true,303);return ['',''];
            }catch(HttpError $e){http_response_code($e->status);$error='<p class="error" role="alert">'.Html::escape($e->getMessage()).' Deine Anordnung bleibt im Editor erhalten.</p>';if($e->status===409){$record['version']=(int)($_POST['version'] ?? -1);}}
        }
        $e=Html::escape(...);$body=$error.(isset($_GET['saved'])?'<p class="success" role="status">Vorlage gespeichert.</p>':'');$csrf='<input type="hidden" name="csrf" value="'.$e($_SESSION['csrf']).'">';
        if($selected===''){$body.=SiteAdmin::presetCards();
            $body.='<div class="template-intro"><p>Gestalte eine Vorlage einmal. Die zugeordneten Seiten füllen Titel, Bilder, Texte und Module automatisch mit ihren eigenen Inhalten.</p><a class="button" href="/admin/templates/?edit=new">Vorlage erstellen</a></div><div class="template-library">';
            foreach($templates as $template){$body.='<article class="template-library-item"><div class="template-wireframe" aria-hidden="true">';foreach(array_slice($template['sections'],0,3) as $section){$body.='<div class="wireframe-row grid-'.$section['layout'].'">';foreach($section['columns'] as $column){$body.='<div>';foreach(array_slice($column,0,3) as $node){$body.='<span class="wireframe-block"></span>';}$body.='</div>';}$body.='</div>';}$body.='</div><div><small>'.count($template['sections']).' Abschnitte · '.count($template['types']).' Inhaltstypen</small><h2>'.$e($template['name']).'</h2><p>'.($template['default_for']?'Standard für '.$e(implode(', ',array_map(fn($type)=>$this->content->schema->type($type)['label'],$template['default_for']))):'Individuell zuweisbar').'</p><a href="/admin/templates/?edit='.$e($template['id']).'">Im visuellen Editor öffnen →</a></div><form method="post">'.$csrf.'<input type="hidden" name="version" value="'.$record['version'].'"><button class="link danger" name="remove" value="'.$e($template['id']).'">Entfernen</button></form></article>';}
            $body.='</div><details><summary>Änderungsverlauf</summary><ul class="revision-list">';foreach($site->history('templates') as $revision){$body.='<li><span>Version '.$revision['version'].' · '.$e($revision['created_at']).'</span><form method="post">'.$csrf.'<input type="hidden" name="version" value="'.$record['version'].'"><button name="restore" value="'.$e($revision['id']).'">Wiederherstellen</button></form></li>';}return ['Vorlagen',$body.'</ul></details>'];
        }
        if(!$candidate){throw new HttpError(404,'Vorlage nicht gefunden.');}
        $fields=['title'=>['label'=>'Seitentitel','kind'=>'title','types'=>[]]];foreach($this->content->schema->types as $typeKey=>$type){foreach($type['fields'] as $key=>$field){if(!($field['admin_hidden'] ?? false)){$fields[$key] ??= ['label'=>$field['label'],'kind'=>$field['presentation'] ?? $field['kind'] ?? 'text','types'=>[]];$fields[$key]['types'][]=$typeKey;}}}
        $widgets=[];foreach((new Placeholders($this->content))->definitions() as $name=>$definition){$widgets[$name]=array_diff_key($definition,['render'=>true]);}
        $samples=[];foreach($this->content->list($actor) as $item){if($item['status']!=='trash'){$samples[]=['id'=>$item['id'],'title'=>$item['title'],'type'=>$item['type']];}}
        $json=json_encode(['template'=>$candidate,'fields'=>$fields,'widgets'=>$widgets,'samples'=>$samples],JSON_THROW_ON_ERROR|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);
        $body.='<a class="text-link" href="/admin/templates/">← Alle Vorlagen</a><form method="post" class="template-form" data-template-builder>'.$csrf.'<input type="hidden" name="version" value="'.$record['version'].'"><textarea name="template_json" data-template-json hidden>'.$e(Store::json($candidate)).'</textarea><script type="application/json" data-builder-data>'.$json.'</script><div class="builder-topbar"><label>Vorlagenname<input name="name" value="'.$e($candidate['name']).'" required maxlength="190"></label><div class="builder-actions"><span data-builder-state role="status">Gespeicherter Stand</span><button type="button" class="secondary" data-builder-undo>Rückgängig</button><button type="button" class="secondary" data-builder-mode>Seitenvorschau</button><button>Vorlage speichern</button></div></div><details class="template-assignment"><summary>Inhaltstypen und automatische Zuweisung</summary><div class="assignment-grid"><fieldset><legend>Für diese Inhalte verfügbar</legend>';
        foreach($this->content->schema->types as $type=>$definition){if($definition['legacy'] ?? false){continue;}$body.='<label class="check"><input type="checkbox" name="types[]" value="'.$e($type).'"'.(in_array($type,$candidate['types'],true)?' checked':'').'>'.$e($definition['label']).'</label>';}
        $body.='</fieldset><fieldset><legend>Standardvorlage verwenden für</legend>';foreach($this->content->schema->types as $type=>$definition){if($definition['legacy'] ?? false){continue;}$body.='<label class="check"><input type="checkbox" name="default_for[]" value="'.$e($type).'"'.(in_array($type,$candidate['default_for'],true)?' checked':'').'>'.$e($definition['label']).'</label>';}
        $body.='</fieldset></div></details><div class="builder-workspace"><aside class="builder-palette"><h2>Elemente</h2><p>Ziehen oder anklicken und in die ausgewählte Spalte einfügen.</p><div data-builder-palette></div><label>Vorschau mit Inhalt<select data-builder-sample aria-label="Vorschau mit Inhalt"></select></label></aside><div class="builder-center"><div class="builder-canvas" data-builder-canvas aria-label="Vorlagenanordnung"></div><iframe class="builder-preview" data-builder-preview title="Vorlagenvorschau" sandbox="allow-same-origin" hidden></iframe><p class="builder-preview-state" data-preview-state role="status"></p><button type="button" class="secondary" data-builder-section>Abschnitt hinzufügen</button></div><aside class="builder-inspector"><h2>Eigenschaften</h2><div data-builder-inspector><p>Wähle ein Element oder einen Abschnitt aus.</p></div></aside></div><noscript><p>Für den visuellen Editor JavaScript aktivieren.</p></noscript></form>';
        return ['Vorlage gestalten',$body];
    }
    public function preview(array $actor):void {
        $this->access->require($actor,'settings');$raw=$_POST['template_json'] ?? '';if(!is_string($raw) || strlen($raw)>1024*1024){throw new HttpError(422,'Vorlage zu groß.');}
        try{$candidate=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new HttpError(422,'Ungültige Vorlage.');}if(!is_array($candidate)){throw new HttpError(422,'Ungültige Vorlage.');}
        $template=Templates::validate([$candidate],$this->content->site->project)[0];$item=$this->content->get((string)($_POST['content_id'] ?? '')) ?? throw new HttpError(404,'Vorschau-Inhalt auswählen.');$this->access->require($actor,'read',$item);if(!in_array($item['type'],$template['types'],true)){throw new HttpError(422,'Der Inhalt passt nicht zu dieser Vorlage.');}
        header('Content-Type: text/html; charset=utf-8');header('X-Robots-Tag: noindex, nofollow');
        $pages=new PageTemplates($this->content,array_replace($this->configuration,['environment'=>'development']));
        if($pages->enabled()){echo $pages->render($item,$template);return;}
        echo '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/templates.css">';foreach($this->content->site->project['preview_styles'] ?? [] as $style){echo '<link rel="stylesheet" href="'.Html::escape($style).'">';}echo '<link rel="stylesheet" href="/assets/site-theme.css"></head><body class="template-preview-document '.Html::escape($this->content->site->project['preview_class'] ?? '').'">'.(new Templates($this->content,$this->configuration))->render($template,$item).'</body></html>';
    }
}
